package numislands

import "testing"

func toGrid(rows []string) [][]byte {
	out := make([][]byte, len(rows))
	for i, r := range rows {
		out[i] = []byte(r)
	}
	return out
}

func TestEmpty(t *testing.T) {
	if got := NumIslands([][]byte{}); got != 0 {
		t.Fatalf("got %d, want 0", got)
	}
}

func TestAllWater(t *testing.T) {
	if got := NumIslands(toGrid([]string{"000", "000", "000"})); got != 0 {
		t.Fatalf("got %d, want 0", got)
	}
}

func TestAllLand(t *testing.T) {
	if got := NumIslands(toGrid([]string{"111", "111", "111"})); got != 1 {
		t.Fatalf("got %d, want 1", got)
	}
}

func TestSingleCell(t *testing.T) {
	if got := NumIslands(toGrid([]string{"1"})); got != 1 {
		t.Fatalf("got %d, want 1", got)
	}
}

func TestClassic(t *testing.T) {
	if got := NumIslands(toGrid([]string{"11000", "11000", "00100", "00011"})); got != 3 {
		t.Fatalf("got %d, want 3", got)
	}
}

func TestDiagonalNotConnected(t *testing.T) {
	if got := NumIslands(toGrid([]string{"101", "010", "101"})); got != 5 {
		t.Fatalf("got %d, want 5", got)
	}
}
